	}
	template <bool Previous>
	std::optional<T> neighbor_scalar(int l, int r, std::uint32_t x) const {
		if (r - l <= 8) {
			std::uint32_t best = Previous ? 0 : static_cast<std::uint32_t>(values.size());
			for (int i = l; i < r; ++i) {
				std::uint32_t c = original[i];
